--
-- Name: email(); Type: FUNCTION; Schema: auth; Owner: postgres
--

CREATE FUNCTION auth.email() RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT
  coalesce(
    current_setting('request.jwt.claim.email', true),
    (current_setting('request.jwt.claims', true)::jsonb ->> 'email')
  )::text
$$;


ALTER FUNCTION auth.email() OWNER TO postgres;

--
-- Name: role(); Type: FUNCTION; Schema: auth; Owner: postgres
--

CREATE FUNCTION auth.role() RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT
  coalesce(
    current_setting('request.jwt.claim.role', true),
    (current_setting('request.jwt.claims', true)::jsonb ->> 'role')
  )::text
$$;


ALTER FUNCTION auth.role() OWNER TO postgres;

--
-- Name: uid(); Type: FUNCTION; Schema: auth; Owner: postgres
--

CREATE FUNCTION auth.uid() RETURNS uuid
    LANGUAGE sql STABLE
    AS $$
  SELECT
  nullif(
    coalesce(
      current_setting('request.jwt.claim.sub', true),
      (current_setting('request.jwt.claims', true)::jsonb ->> 'sub')
    ),
    ''
  )::uuid
$$;


ALTER FUNCTION auth.uid() OWNER TO postgres;

--
-- Name: update_campaign_stats_trigger(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.update_campaign_stats_trigger() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    SELECT 
        NEW.campaign_id,
        COALESCE(SUM(CASE WHEN status IN ('SENT', 'REPLIED') THEN 1 ELSE 0 END), 0) as total_sent,
        COALESCE(SUM(CASE WHEN status = 'REPLIED' THEN 1 ELSE 0 END), 0) as total_replied,
        CASE 
            WHEN SUM(CASE WHEN status IN ('SENT', 'REPLIED') THEN 1 ELSE 0 END) > 0 
            THEN ROUND((SUM(CASE WHEN status = 'REPLIED' THEN 1 ELSE 0 END) * 100.0 / SUM(CASE WHEN status IN ('SENT', 'REPLIED') THEN 1 ELSE 0 END)), 2)
            ELSE 0 
        END as reply_rate,
        NOW()
    FROM leads
    WHERE campaign_id = NEW.campaign_id
    ON CONFLICT (campaign_id) DO UPDATE SET
        total_sent = EXCLUDED.total_sent,
        total_replied = EXCLUDED.total_replied,
        reply_rate = EXCLUDED.reply_rate,
        last_synced_at = EXCLUDED.last_synced_at;
        
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.update_campaign_stats_trigger() OWNER TO postgres;

--
-- Name: update_lead_status_from_webhook(uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.update_lead_status_from_webhook(p_campaign_id uuid, p_email text, p_event text, p_gmail_message_id text DEFAULT NULL::text, p_gmail_thread_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_lead_id UUID;
    v_new_status TEXT;
    v_reply_count INT;
BEGIN
    -- Determine new status
    CASE p_event
        WHEN 'EMAIL_SENT' THEN v_new_status := 'SENT';
        WHEN 'EMAIL_REPLY' THEN v_new_status := 'REPLIED';
        WHEN 'EMAIL_FAILED' THEN v_new_status := 'FAILED';
        WHEN 'EMAIL_BOUNCED' THEN v_new_status := 'BOUNCED';
        ELSE 
            RETURN jsonb_build_object('success', false, 'error', 'Invalid event type');
    END CASE;

    -- Find the lead
    SELECT id, reply_count INTO v_lead_id, v_reply_count
    FROM leads
    WHERE campaign_id = p_campaign_id AND email = p_email
    LIMIT 1;

    IF v_lead_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Lead not found');
    END IF;

    -- Update the lead
    UPDATE leads
    SET 
        status = v_new_status,
        sent_at = CASE WHEN p_event = 'EMAIL_SENT' THEN NOW() ELSE sent_at END,
        replied_at = CASE WHEN p_event = 'EMAIL_REPLY' THEN NOW() ELSE replied_at END,
        reply_count = CASE WHEN p_event = 'EMAIL_REPLY' THEN COALESCE(v_reply_count, 0) + 1 ELSE reply_count END,
        gmail_message_id = COALESCE(p_gmail_message_id, gmail_message_id),
        gmail_thread_id = COALESCE(p_gmail_thread_id, gmail_thread_id)
    WHERE id = v_lead_id;

    RETURN jsonb_build_object('success', true, 'lead_id', v_lead_id);
END;
$$;


ALTER FUNCTION public.update_lead_status_from_webhook(p_campaign_id uuid, p_email text, p_event text, p_gmail_message_id text, p_gmail_thread_id text) OWNER TO postgres;

